#!/usr/bin/env python3
"""
Round 163m (culprits), 4 October 2026. Needs round 162m.

Mother Earth basemap: purple only in the sky; earth-toned land.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 163m (4 October)\n\nNeeds round 162m. No tiles patch. No app.js?v= bump.\n\n- Owner on 162m: way too purple; the painting's purples and blues are its\n  sky, not the colour of the land. Mother Earth recoloured: the violets kept\n  only in the sky round the globe (MOTHER.sky, unchanged).\n- Land and water now follow the painting's land: forests deep muted spruce\n  (MOTHER.pines), bare ground and rock warm earth to pale stone on lit faces\n  (MOTHER.stone), seas and lakes deep blue-teal (MOTHER.waters, MOTHER.sea,\n  lake, river), snow a cool white, high-ground haze a thin cool blue-grey,\n  hillshade light warm bone and shadows dark slate, towns, roads and\n  buildings umber, borders bone. Place names pale bone on a dark slate halo\n  (seas still pale cyan). The (i) note's wording follows.\n- Only open water glows near land (Open, a blur of the water mask): a lone\n  dark-blue speck, such as a shadow read as water, is left unlit.\n- Checked on sample world-view satellite tiles in Chromium; not seen against\n  the live tiles.\n"]
DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round163m: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 162m" not in h.read_text(encoding="utf-8"):
        sys.exit("round163m: round 162m must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round163m: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round163m: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round163m: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
